<?php
function current_language(): string
{
    $requested = $_GET['lang'] ?? $_POST['lang'] ?? $_SESSION['dev_language'] ?? 'de';
    if (is_string($requested) && in_array($requested, ['de', 'en', 'ru'], true)) { $_SESSION['dev_language'] = $requested; }
    return $_SESSION['dev_language'] ?? 'de';
}
